import{_ as t,o as s,c as i,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 20 章 记忆系统进阶：长期协作上下文","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md"}'),n={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md"};function l(o,a,r,d,h,p){return s(),i("div",null,[...a[0]||(a[0]=[e(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 20 章 记忆系统进阶：长期协作上下文（易懂版）](../../easy/第20章 记忆系统进阶：长期协作上下文（易懂版）.md)</p></div><h1 id="第-20-章-记忆系统进阶-长期协作上下文" tabindex="-1">第 20 章 记忆系统进阶：长期协作上下文 <a class="header-anchor" href="#第-20-章-记忆系统进阶-长期协作上下文" aria-label="Permalink to &quot;第 20 章 记忆系统进阶：长期协作上下文&quot;">​</a></h1><blockquote><p>本章目标：把记忆从&quot;几条偏好&quot;升级为<strong>长期协作上下文</strong>——掌握三阶段建设法、记忆治理与隐私边界。<strong>记忆是时间的朋友：用得越久，我越懂你；越懂你，每次任务就越省沟通、越少返工。</strong></p></blockquote><h2 id="_20-1-从-记住-到-协作上下文" tabindex="-1">20.1 从&quot;记住&quot;到&quot;协作上下文&quot; <a class="header-anchor" href="#_20-1-从-记住-到-协作上下文" aria-label="Permalink to &quot;20.1 从&quot;记住&quot;到&quot;协作上下文&quot;&quot;">​</a></h2><p>第 6 章讲了记忆的基础用法。这一章进阶：把记忆从&quot;几条偏好&quot;升级成<strong>你和 AI 之间的长期协作上下文</strong>——让任何一次新会话，都像老搭档接着聊。</p><h3 id="_20-1-1-差别的本质" tabindex="-1">20.1.1 差别的本质 <a class="header-anchor" href="#_20-1-1-差别的本质" aria-label="Permalink to &quot;20.1.1 差别的本质&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础用法：记住几条事实（&quot;用户偏好中文&quot;）</span></span>
<span class="line"><span>协作上下文：完整理解你（你是谁、在做什么、偏好什么、上次聊到哪、有哪些坑）</span></span></code></pre></div><p><strong>协作上下文 = 事实 + 决策 + 关系 + 状态</strong>。有了它，我在新任务里少问 10 个问题。</p><h2 id="_20-2-记忆的四种类型回顾" tabindex="-1">20.2 记忆的四种类型回顾 <a class="header-anchor" href="#_20-2-记忆的四种类型回顾" aria-label="Permalink to &quot;20.2 记忆的四种类型回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>用途</th><th>例子</th></tr></thead><tbody><tr><td>user</td><td>关于你</td><td>身份、角色、工作背景</td></tr><tr><td>feedback</td><td>你的反馈</td><td>风格偏好、踩过的坑</td></tr><tr><td>project</td><td>项目上下文</td><td>项目目标、决策、现状</td></tr><tr><td>reference</td><td>参考资料</td><td>模板、规范、参考文档</td></tr></tbody></table><p><strong>进阶心法：记忆不是&quot;存档&quot;，而是&quot;上下文&quot;。</strong> 好的记忆，让我在新任务里少问 10 个问题。</p><h2 id="_20-3-长期协作上下文怎么建立-三阶段" tabindex="-1">20.3 长期协作上下文怎么建立：三阶段 <a class="header-anchor" href="#_20-3-长期协作上下文怎么建立-三阶段" aria-label="Permalink to &quot;20.3 长期协作上下文怎么建立：三阶段&quot;">​</a></h2><h3 id="第一阶段-初始化-一次性投入" tabindex="-1">第一阶段：初始化（一次性投入） <a class="header-anchor" href="#第一阶段-初始化-一次性投入" aria-label="Permalink to &quot;第一阶段：初始化（一次性投入）&quot;">​</a></h3><p>花 10 分钟，把稳定的背景一次说清：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;记住：我是产品经理，主要做 B 端 SaaS；文档偏好结论先行、</span></span>
<span class="line"><span>中文简洁；所有交付物用 Markdown；我所在项目是 XX。&quot;</span></span></code></pre></div><p><strong>初始化解决的问题：</strong> 从此不用每次重复自我介绍和偏好。</p><h3 id="第二阶段-运行期沉淀-持续投入" tabindex="-1">第二阶段：运行期沉淀（持续投入） <a class="header-anchor" href="#第二阶段-运行期沉淀-持续投入" aria-label="Permalink to &quot;第二阶段：运行期沉淀（持续投入）&quot;">​</a></h3><p>每次任务结束，沉淀一条——<strong>把&quot;过程&quot;变成&quot;资产&quot;</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务做完后 → 记录：项目当前状态、下一步计划、本轮的坑</span></span></code></pre></div><p><strong>沉淀的时机（三个最好）：</strong></p><ul><li>任务完成时（总结成功路径）；</li><li>任务失败时（记录踩坑教训）；</li><li>决策变更时（记录原因，避免重复解释）。</li></ul><h3 id="第三阶段-定期整理-维护" tabindex="-1">第三阶段：定期整理（维护） <a class="header-anchor" href="#第三阶段-定期整理-维护" aria-label="Permalink to &quot;第三阶段：定期整理（维护）&quot;">​</a></h3><ul><li>过期记忆删除或更新；</li><li>重复记忆合并；</li><li>索引（MEMORY.md）保持整洁，一条一行。</li></ul><p><strong>记忆不维护，就会像仓库一样越堆越乱。</strong> 每月花 5 分钟整理一次，性价比极高。</p><h2 id="_20-4-记忆的最佳实践" tabindex="-1">20.4 记忆的最佳实践 <a class="header-anchor" href="#_20-4-记忆的最佳实践" aria-label="Permalink to &quot;20.4 记忆的最佳实践&quot;">​</a></h2><h3 id="值得长期记忆的" tabindex="-1">值得长期记忆的 <a class="header-anchor" href="#值得长期记忆的" aria-label="Permalink to &quot;值得长期记忆的&quot;">​</a></h3><ul><li>稳定的工作方式（&quot;我每周五要周报&quot;）；</li><li>关键决策与原因（&quot;我们选 A 方案因为成本，别再说 B&quot;）；</li><li>名词解释（团队内部术语，每次都要解释太浪费）。</li></ul><h3 id="不值得记忆的" tabindex="-1">不值得记忆的 <a class="header-anchor" href="#不值得记忆的" aria-label="Permalink to &quot;不值得记忆的&quot;">​</a></h3><ul><li>一次性数据（放项目文件）；</li><li>会变的内容（放文件或数据库）；</li><li>敏感信息（明文记忆文件，不存密钥密码）。</li></ul><h3 id="_20-4-1-记忆的最佳结构" tabindex="-1">20.4.1 记忆的最佳结构 <a class="header-anchor" href="#_20-4-1-记忆的最佳结构" aria-label="Permalink to &quot;20.4.1 记忆的最佳结构&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: 用户工作背景</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: 身份与工作方式</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type: user</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 身份：产品经理，B 端 SaaS</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 偏好：结论先行、中文简洁</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 常用格式：Markdown</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 项目：MomaWork 白皮书</span></span></code></pre></div><p><strong>结构化的记忆（列表/分类）比散文更容易被检索和复用。</strong></p><h2 id="_20-5-记忆的治理与隐私" tabindex="-1">20.5 记忆的治理与隐私 <a class="header-anchor" href="#_20-5-记忆的治理与隐私" aria-label="Permalink to &quot;20.5 记忆的治理与隐私&quot;">​</a></h2><h3 id="_20-5-1-治理三原则" tabindex="-1">20.5.1 治理三原则 <a class="header-anchor" href="#_20-5-1-治理三原则" aria-label="Permalink to &quot;20.5.1 治理三原则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>做法</th></tr></thead><tbody><tr><td>透明</td><td>记忆文件是明文，你随时可读</td></tr><tr><td>可控</td><td>随时删除：&quot;忘掉 XXX&quot;</td></tr><tr><td>卫生</td><td>定期清理过期、合并重复</td></tr></tbody></table><h3 id="_20-5-2-隐私红线" tabindex="-1">20.5.2 隐私红线 <a class="header-anchor" href="#_20-5-2-隐私红线" aria-label="Permalink to &quot;20.5.2 隐私红线&quot;">​</a></h3><ul><li>记忆文件是<strong>明文</strong>，放在项目对应目录，你可以随时读；</li><li>敏感项目：注意记忆文件不要提交到公开仓库；</li><li>团队协作：共享项目的记忆是团队资产，写入前想清楚；</li><li><strong>密钥、密码、token 永远不进记忆文件。</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">安全提醒</p><p><strong>记忆不是保险箱。</strong> 明文存放，任何人都能读。机密信息要么用环境变量、要么一次性会话处理，用完即弃。</p></div><h2 id="_20-6-记忆让-老搭档-成为可能" tabindex="-1">20.6 记忆让&quot;老搭档&quot;成为可能 <a class="header-anchor" href="#_20-6-记忆让-老搭档-成为可能" aria-label="Permalink to &quot;20.6 记忆让&quot;老搭档&quot;成为可能&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有记忆的 AI：每次都是新员工，从头自我介绍</span></span>
<span class="line"><span>有记忆的 AI：知道你是谁、在做什么、偏好什么、上次聊到哪</span></span></code></pre></div><p>这套上下文，是第 17 章 Skill、第 18 章系统、第 19 章自动化的<strong>底座</strong>——它们都要靠记忆来&quot;认得你&quot;。</p><h3 id="_20-6-1-记忆-×-其他章节的放大效应" tabindex="-1">20.6.1 记忆 × 其他章节的放大效应 <a class="header-anchor" href="#_20-6-1-记忆-×-其他章节的放大效应" aria-label="Permalink to &quot;20.6.1 记忆 × 其他章节的放大效应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组合</th><th>效果</th></tr></thead><tbody><tr><td>记忆 + Skill</td><td>Skill 自动适配你的偏好</td></tr><tr><td>记忆 + 自动化</td><td>工作流按你的习惯定制</td></tr><tr><td>记忆 + 团队</td><td>团队成员共享项目上下文</td></tr><tr><td>记忆 + 多 Agent</td><td>整个系统都&quot;认得你&quot;</td></tr></tbody></table><h2 id="_20-7-记忆体检-三个月后的样子" tabindex="-1">20.7 记忆体检：三个月后的样子 <a class="header-anchor" href="#_20-7-记忆体检-三个月后的样子" aria-label="Permalink to &quot;20.7 记忆体检：三个月后的样子&quot;">​</a></h2><p><strong>三个月后，一份健康的记忆应该长这样：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MEMORY.md（索引，一条一行）</span></span>
<span class="line"><span>├── user/（3~5 条）：身份、偏好、习惯</span></span>
<span class="line"><span>├── feedback/（5~10 条）：你的反馈与我的调整</span></span>
<span class="line"><span>├── project/（若干）：每个项目一行状态</span></span>
<span class="line"><span>└── reference/（若干）：常用模板、规范</span></span></code></pre></div><p><strong>如果记忆超过 50 条还没整理过，说明该体检了。</strong></p><h2 id="_20-8-练习" tabindex="-1">20.8 练习 <a class="header-anchor" href="#_20-8-练习" aria-label="Permalink to &quot;20.8 练习&quot;">​</a></h2><ol><li>花 10 分钟做一次&quot;记忆初始化&quot;：身份、偏好、项目、常用格式；</li><li>本周每次任务完成后，沉淀一条 project/feedback 记忆；</li><li>周末检查 MEMORY.md 索引，合并重复、删除过期；</li><li>检查记忆里有没有敏感信息（密钥/密码），有就立即删除。</li></ol><hr><blockquote><p>小结：记忆系统是<strong>时间的朋友</strong>。用得越久，我越懂你；越懂你，每次任务就越省沟通、越少返工。<strong>三阶段建设（初始化→沉淀→整理）+ 治理三原则（透明/可控/卫生）</strong>，就是长期协作的全部心法。下一篇：让能力落进岗位与行业。</p></blockquote>`,51)])])}const k=t(n,[["render",l]]);export{u as __pageData,k as default};
